void logit(int data_type, int display, const char *fmt, ...) { /* <=== logit */ 
	va_list ap;
	char *buffer = NULL;

	va_start(ap, fmt);
	if(vasprintf(&buffer, fmt, ap) > 0) {
		write_to_logs_and_console(buffer, data_type, display);
		free(buffer);
		}
	va_end(ap);
	}

void *dkhash_get(dkhash_table *t, const char *k1, const char *k2) /* <=== dkhash_get */ 
{
	dkhash_bucket *bkt;
	unsigned int slot;

	if (!t || !k1)
		return NULL;

	slot = dkhash_slot(t, k1, k2);
	bkt = k2 ? dkhash_get_bucket2(t, k1, k2, slot) : dkhash_get_bucket(t, k1, slot);

	return bkt ? bkt->data : NULL;
}

void kvvec_free_kvpairs(struct kvvec *kvv, int flags) /* <=== kvvec_free_kvpairs */ 
{
	int i;

	if (flags == KVVEC_FREE_ALL) {
		for (i = 0; i < kvv->kv_pairs; i++) {
			free(kvv->kv[i].key);
			free(kvv->kv[i].value);
		}
	} else if (flags == KVVEC_FREE_KEYS) {
		for (i = 0; i < kvv->kv_pairs; i++) {
			free(kvv->kv[i].key);
		}
	} else if (flags == KVVEC_FREE_VALUES) {
		for (i = 0; i < kvv->kv_pairs; i++) {
			free(kvv->kv[i].value);
		}
	}

	kvv->kv_pairs = 0;
}

static dkhash_bucket *dkhash_get_bucket(dkhash_table *t, const char *key, unsigned int slot) /* <=== dkhash_get_bucket */ 
{
	dkhash_bucket *bkt;

	for (bkt = t->buckets[slot]; bkt; bkt = bkt->next) {
		if (!strcmp(key, bkt->key))
			return bkt;
	}

	return NULL;
}

