struct kvvec *kvvec_create(int hint) /* <=== kvvec_create */ 
{
	struct kvvec *kvv = calloc(1, sizeof(*kvv));
	if (kvv && !kvvec_init(kvv, hint)) {
		free(kvv);
		return NULL;
	}
	return kvv;
}

int dump_event_stats(int sd) /* <=== dump_event_stats */ 
{
	unsigned int i;

	for (i = 0; i < ARRAY_SIZE(event_count); i++) {
		nsock_printf(sd, "%s=%u;", EVENT_TYPE_STR(i), event_count[i]);
		/*
		 * VERSIONFIX: Make EVENT_SLEEP and EVENT_USER_FUNCTION
		 * appear in linear order in include/nagios.h when we go
		 * from 4.0 -> 4.1, so we can remove this junk.
		 */
		if (i == 16)
			i = 97;
		}
	nsock_printf_nul(sd, "SQUEUE_ENTRIES=%u", squeue_size(nagios_squeue));

	return OK;
	}

int write_to_all_logs(char *buffer, unsigned long data_type) { /* <=== write_to_all_logs */ 

	/* write to syslog */
	write_to_syslog(buffer, data_type);

	/* write to main log */
	write_to_log(buffer, data_type, NULL);

	return OK;
	}

static inline int nsock_vprintf(int sd, const char *fmt, va_list ap, int plus) /* <=== nsock_vprintf */ 
{
	va_list ap_dup;
	char stack_buf[4096];
	int len;

	va_copy(ap_dup, ap);
	len = vsnprintf(stack_buf, sizeof(stack_buf), fmt, ap_dup);
	va_end(ap_dup);
	if (len < 0)
		return len;

	if (len < sizeof(stack_buf)) {
		stack_buf[len] = 0;
		if (plus) ++len; /* Include the nul byte if requested. */
		return write(sd, stack_buf, len);

	} else {
		char *heap_buf = NULL;

		len = vasprintf(&heap_buf, fmt, ap);
		if (len < 0)
			return len;

		if (plus) ++len; /* Include the nul byte if requested. */
		len = write(sd, heap_buf, len);
		free(heap_buf);
		return len;
	}
}

unsigned int /* <=== pqueue_size */ 
pqueue_size(pqueue_t *q)
{
	/* queue element 0 exists but doesn't count since it isn't used. */
	return (q->size - 1);
}

int kvvec_destroy(struct kvvec *kvv, int flags) /* <=== kvvec_destroy */ 
{
	kvvec_free_kvpairs(kvv, flags);
	free(kvv->kv);
	free(kvv);
	return 0;
}

static void write_to_logs_and_console(char *buffer, unsigned long data_type, int display) { /* <=== write_to_logs_and_console */ 
	register int len = 0;
	register int x = 0;

	/* strip unnecessary newlines */
	len = strlen(buffer);
	for(x = len - 1; x >= 0; x--) {
		if(buffer[x] == '\n')
			buffer[x] = '\x0';
		else
			break;
		}

	/* write messages to the logs */
	write_to_all_logs(buffer, data_type);

	/* write message to the console */
	if(display == TRUE) {

		/* don't display warnings if we're just testing scheduling */
		if(test_scheduling == TRUE && data_type == NSLOG_VERIFICATION_WARNING)
			return;

		write_to_console(buffer);
		}
	}

struct kvvec *buf2kvvec(char *str, unsigned int len, const char kvsep, /* <=== buf2kvvec */ 
			const char pair_sep, int flags)
{
	struct kvvec *kvv;

	kvv = kvvec_create(len / 20);
	if (!kvv)
		return NULL;

	if (buf2kvvec_prealloc(kvv, str, len, kvsep, pair_sep, flags) >= 0)
		return kvv;

	free(kvv);
	return NULL;
}

static dkhash_bucket *dkhash_get_bucket2(dkhash_table *t, const char *k1, const char *k2, unsigned int slot) /* <=== dkhash_get_bucket2 */ 
{
	dkhash_bucket *bkt;

	for (bkt = t->buckets[slot]; bkt; bkt = bkt->next) {
		if (!strcmp(k1, bkt->key) && bkt->key2 && !strcmp(k2, bkt->key2))
			return bkt;
		}

	return NULL;
}

